INSERT INTO public.commercial_item_catalog (
  sku,
  code,
  name,
  description,
  category,
  unit,
  purchase_price,
  default_unit_price,
  default_vat_rate,
  currency,
  product_type,
  source,
  is_active,
  image_url,
  metadata,
  updated_at
)
SELECT
  sku,
  code,
  name,
  NULLIF(description, ''),
  category,
  COALESCE(NULLIF(unit, ''), 'ks'),
  COALESCE(purchase_price, 0),
  COALESCE(default_unit_price, 0),
  COALESCE(default_vat_rate, 21),
  COALESCE(NULLIF(currency, ''), 'CZK'),
  COALESCE(NULLIF(product_type, ''), 'manufactured'),
  'import',
  COALESCE(is_active, true),
  NULLIF(image_url, ''),
  COALESCE(metadata, '{}'::jsonb) || jsonb_build_object(
    'vendor_import', 'krannich_20260704',
    'supplier', 'Krannich Solar',
    'last_supplier_sync_at', now()
  ),
  now()
FROM source_rows
ON CONFLICT ((lower(sku))) WHERE sku IS NOT NULL AND sku <> ''
DO UPDATE SET
  code = EXCLUDED.code,
  name = EXCLUDED.name,
  description = EXCLUDED.description,
  category = EXCLUDED.category,
  unit = EXCLUDED.unit,
  purchase_price = EXCLUDED.purchase_price,
  default_unit_price = CASE
    WHEN commercial_item_catalog.source = 'import'
      OR commercial_item_catalog.default_unit_price = commercial_item_catalog.purchase_price
      OR commercial_item_catalog.default_unit_price = 0
    THEN EXCLUDED.default_unit_price
    ELSE commercial_item_catalog.default_unit_price
  END,
  default_vat_rate = EXCLUDED.default_vat_rate,
  currency = EXCLUDED.currency,
  product_type = EXCLUDED.product_type,
  source = CASE WHEN commercial_item_catalog.source = 'manual' THEN commercial_item_catalog.source ELSE 'import' END,
  is_active = true,
  image_url = COALESCE(EXCLUDED.image_url, commercial_item_catalog.image_url),
  metadata = COALESCE(commercial_item_catalog.metadata, '{}'::jsonb)
    || COALESCE(EXCLUDED.metadata, '{}'::jsonb)
    || jsonb_build_object(
      'vendor_import', 'krannich_20260704',
      'supplier', 'Krannich Solar',
      'last_supplier_sync_at', now()
    ),
  archived_at = NULL,
  updated_at = now();

